"use client";
/* Fireflies, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Fireflies(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("fireflies"); }, []);
  return React.createElement("piix-pal", { "pal": "fireflies", ...piixAttrs(props) });
}

export default Fireflies;
